	// MurmurHash3 x86_32, seed 0 - the Halo 5 string id function.
	constexpr uint32_t murmur3(std::string_view s) noexcept
	{
		constexpr uint32_t c1 = 0xcc9e2d51u, c2 = 0x1b873593u;
		uint32_t h = 0;
		const size_t n = s.size();
		const size_t nblocks = n / 4;
		for (size_t i = 0; i < nblocks; ++i)
		{
			uint32_t k = (uint32_t)(uint8_t)s[i * 4]
				| ((uint32_t)(uint8_t)s[i * 4 + 1] << 8)
				| ((uint32_t)(uint8_t)s[i * 4 + 2] << 16)
				| ((uint32_t)(uint8_t)s[i * 4 + 3] << 24);
			k *= c1; k = (k << 15) | (k >> 17); k *= c2;
			h ^= k; h = (h << 13) | (h >> 19); h = h * 5u + 0xe6546b64u;
		}
		uint32_t k = 0;
		const size_t tail = nblocks * 4;
		switch (n & 3u)
		{
		case 3: k |= (uint32_t)(uint8_t)s[tail + 2] << 16; [[fallthrough]];
		case 2: k |= (uint32_t)(uint8_t)s[tail + 1] << 8;  [[fallthrough]];
		case 1: k |= (uint32_t)(uint8_t)s[tail];
			k *= c1; k = (k << 15) | (k >> 17); k *= c2; h ^= k;
		default: break;
		}
		h ^= (uint32_t)n;
		h ^= h >> 16; h *= 0x85ebca6bu;
		h ^= h >> 13; h *= 0xc2b2ae35u;
		h ^= h >> 16;
		return h;
	}

	inline const Entry* find(uint32_t hash) noexcept
	{
		const auto it = std::lower_bound(kEntries.begin(), kEntries.end(), hash,
			[](const Entry& e, uint32_t h) { return e.hash < h; });
		if (it != kEntries.end() && it->hash == hash) return &*it;
		return nullptr;
	}

	// Empty when the hash is not in the corpus.
	inline std::string_view lookup(uint32_t hash) noexcept
	{
		const Entry* e = find(hash);
		return e ? std::string_view(e->name) : std::string_view{};
	}

	inline ScriptTier tierOf(uint32_t hash) noexcept
	{
		const Entry* e = find(hash);
		return e ? e->tier : ScriptTier::Unknown;
	}

	// "A script can hit or wake this." Poll/enumerate/act all count; a reference that only exists inside
	// commented-out code does NOT.
	constexpr bool isScriptReachable(ScriptTier t) noexcept
	{
		return t == ScriptTier::Test || t == ScriptTier::Query
			|| t == ScriptTier::Action || t == ScriptTier::Goto;
	}

	constexpr std::string_view tierName(ScriptTier t) noexcept
	{
		switch (t)
		{
		case ScriptTier::Test:          return "script-tested";
		case ScriptTier::Query:         return "script-queried";
		case ScriptTier::Action:        return "script-acted-on";
		case ScriptTier::Goto:          return "script-goto";
		case ScriptTier::CommentOnly:   return "commented-out only";
		case ScriptTier::EngineZoneSet: return "engine zone set";
		default:                        return "no script reference";
		}
	}
